ALTER TABLE public.orders ADD COLUMN IF NOT EXISTS whatsapp_manually_confirmed_at timestamptz, ADD COLUMN IF NOT EXISTS whatsapp_manually_confirmed_by uuid;
CREATE OR REPLACE FUNCTION public.confirm_whatsapp_manually(p_order_id uuid) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$ DECLARE v_order public.orders%ROWTYPE; BEGIN IF auth.uid() IS NULL OR NOT public.is_admin(auth.uid()) THEN RAISE EXCEPTION 'Administrators only'; END IF; SELECT * INTO v_order FROM public.orders WHERE id=p_order_id FOR UPDATE; IF NOT FOUND THEN RAISE EXCEPTION 'Order not found'; END IF; IF v_order.payment_status <> 'confirmed' THEN RAISE EXCEPTION 'Confirmed payment required'; END IF; IF v_order.whatsapp_manually_confirmed_at IS NOT NULL THEN RETURN jsonb_build_object('success', true, 'duplicate', true); END IF; UPDATE public.orders SET whatsapp_manually_confirmed_at=now(), whatsapp_manually_confirmed_by=auth.uid(), n8n_response_message='تم تأكيد إرسال واتساب يدويًا بواسطة الإدارة', n8n_responded_at=now() WHERE id=p_order_id; INSERT INTO public.activity_logs(activity_type,user_type,user_identifier,action_data) VALUES ('whatsapp_manual_confirmation','admin',auth.uid()::text,jsonb_build_object('order_id',p_order_id,'booking_reference',v_order.booking_reference)); RETURN jsonb_build_object('success',true); END; $$;
REVOKE ALL ON FUNCTION public.confirm_whatsapp_manually(uuid) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.confirm_whatsapp_manually(uuid) TO authenticated;